import { Path } from "@effect/platform";
import { Effect } from "effect";

export const computeClaudeProjectFilePath = (options: {
  projectPath: string;
  claudeProjectsDirPath: string;
}) =>
  Effect.gen(function* () {
    const path = yield* Path.Path;
    const { projectPath, claudeProjectsDirPath } = options;

    // Claude Code 会将路径中的 / 和 _ 都替换成 -
    // 这样可以确保生成的目录名与 Claude Code 实际创建的目录名一致
    return path.join(
      claudeProjectsDirPath,
      projectPath.replace(/\/$/, "").replace(/[/_]/g, "-"),
    );
  });
